        v::<FqAddGroup>(groups.checked_mul(2)?, false)?.checked_add(v::<[Fq; 5]>(tail, true)?)
    } else {
        v::<Fq2AddGroup>(groups, false)?.checked_add(v::<[Fq2; 5]>(tail, true)?)
    }
}

