        .checked_add(pairs)?
        .checked_add(groups)?
        .checked_add(jobs.checked_mul(3 * 64)?)?
        .checked_add(jobs.checked_mul(core::mem::size_of::<Vec<[FqBatch; 2]>>())?)
}

